using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class OriginalNormalFamilyDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/Foundation/OriginalNormalFamily.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original normal positivity, common scale and sharp whole-face budgets", H("Original normal positivity, common scale and sharp whole-face budgets"), Blocks(
            Paragraph(Text("V is an arbitrary finite dimensional real normed space, C a pointed cone, and u its original linear unit. Where stated, C is closed and generating and u is strictly positive on nonzero C. K is the entire normalized base and P its entire extreme locus. All original linear effects between zero and u are retained; the full confirming family F(p) includes u. Pure reciprocity exchanges only two pure endpoints. No mixed reciprocity, matrix specialization, weakPair, unit-width assumption or global uniform-fiber premise is used.")),
            Describe.Lean(DescribeId.Create("rho-positive-iff"), DeclarationHandle.Create(Owner + "rho_positive_iff"),
                H("Exact whole-cone support threshold"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("In addition to closedness, strict positivity, generation and EB, assume Inj. Fix an original p, an entire chart a, ep in its full zero-confirming fiber, and Coordinates k supplied by the original restriction owner in the singleton branch. Set g=u-ep, D(v)=directionLift(k,v), and normalForm(k,alpha,v)=alpha g+D(v) as an original linear functional on all V. rho(k,v) is the supremum of -D(v)(x)/g(x) over every x in K except p. For every unit v the supremum is bounded, rho>=1, and normalForm is nonnegative on all C exactly when alpha>=rho. No positivity is inferred from an upper bound."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("normal-maximum"), DeclarationHandle.Create(Owner + "normal_maximum"),
                H("Maximum after positivity is established"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Assume closedness, strict positivity and generation, with p,a,ep,k as above. For arbitrary real alpha and arbitrary vector v, if normalForm is nonnegative on the entire C, its value on all K is at most alpha+norm(v), and this value is attained at an actual point of the whole D(p). This uses the existing positive-annihilator maximum owner and the original chart formula. The positivity premise is indispensable."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-neighbor-support"), DeclarationHandle.Create(Owner + "original_neighbor_support"),
                H("Actual neighboring confirmer and antipode"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Under EB and Inj, for every original unit v and original pure q=a(v), the entire full zero-confirming fiber at q is a singleton eq. With lambda=1/(1+rho(k,v)), 0<lambda<=1/2 and eq(x)=(1-lambda)g(x)+lambda D(v)(x) for every x in V. At the actual old antipode a(-v), eq equals (rho-1)/(rho+1), and this antipode belongs to the whole D(q) exactly when rho=1. The exact original neighbor-uniqueness, lift and domination owners are consumed, preserving their proofs."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-coordinate-map"), DeclarationHandle.Create(Owner + "original_coordinate_map"),
                H("Unique actual linear coordinate map"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For any Coordinates k of the actual original normal restriction, coordinateMap(k) is a linear H from all V to the chart coordinate space. H(p)=0, H(a(z))=z for every coordinate z, and every scalar component inner(v,H(x)) is represented by an element of the actual normal span. Among all original linear maps with those normal-span components and the same whole-chart values, H is unique. The construction uses inverse Riesz representation of the actual inverse-restriction direction lifts. In original_row_saturation, k is obtained from original_coordinates under EB3, Inj and the exact singleton full zero-confirming fiber; Coordinates is not supplied as a desired output of that theorem."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-whole-edge"), DeclarationHandle.Create(Owner + "original_whole_edge"),
                H("Full opposite edge interval"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Under EB and Inj with the same actual normal data, every original proper b with b(p)=0 and b(q)=1 is exactly (1-s)(u-ep)+s eq for some s in [0,1], as an equality of functionals on the entire V. Conversely every such convex combination is proper and has those endpoint readings. A common actual zero point different from p bounds the coefficient by the unique neighboring confirmer coefficient."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-fixed-edge"), DeclarationHandle.Create(Owner + "original_fixed_edge"),
                H("Complete fixed edge J(p,q)"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For the same original data, the entire original edge of proper e with e(p)=1 and e(q)=0 is exactly e=(1-s)ep+s(u-eq), s in [0,1], on all V. This is the complement of the full opposite edge, retaining every original effect. original_row_saturation consumes this interface to turn exact fixed-edge attainment into the pure-row minimum."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("pure-row-positive-bridge"), DeclarationHandle.Create(Owner + "pure_row_positive_bridge"),
                H("Pure row to a genuinely positive original effect"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Assume the original normal data, a proper full confirmer eq at q, a positive lambda, its whole-V normal formula, and the exact pure-row equality T(p,s)=min(ep(s),(u-eq)(s)) for every original pure s. The theorem proves that b=(g+D(v))/2 is proper on all C, b(p)=0, b(q)=1 and b(a(-v))=0; hence the actual old antipode belongs to D(q). The proof first obtains whole-C positivity by perturbing g in the direction of H(s). Direction domination pays positivity, and only then the whole-base maximum normalizes the perturbation into an actual effect. Complementing that effect uses the entire F(p). A negative reading of g+D(v) contradicts the exact pure row. The pure-row premise is a required protected join and is not asserted for an actual collapse by this module."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-ball-scale"), DeclarationHandle.Create(Owner + "original_ball_scale"),
                H("Common scale on the whole ball"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Assume closedness, strict positivity, generation, EB and pure reciprocity. For every pure p and every finite nondegenerate ExclusionChart a of its entire D(p), there is one t with 0<t<=1/2. For every unit direction v and pure q=a(v), a single original confirming effect e of q has e(a(z))=1-t+t inner(v,z) for every z in the whole affine chart. The same e attains T(q,a(z)) for every mixed coordinate with norm(z)<=1. No Inj or singleton confirming fiber is assumed. The proof chooses an actual minimizing effect at the antipode, uses the original peak formula, and compares distinct pure directions using PR. Strict endpoint exposure rules out zero scale."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-scale-and-sharp-budget"), DeclarationHandle.Create(Owner + "original_scale_and_sharp_budget"),
                H("Attained optimal original budget"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Under the same original hypotheses and arbitrary chart, choose the same common t as in the whole-ball law. For each unit v, BudgetFeasible(a,v,M) means M>=0 and an actual original linear g obeys 0<=g<=M u on all C and g(a(z))=(1+inner(v,z))/2 on the entire closed ball. extensionBudget is the infimum of this actual feasible set. The theorem supplies feasibility at 1/(2t), proves every feasible M is at least 1/(2t), and identifies the infimum with this value. The set is proved nonempty and bounded below. The attaining extension is the complement of an actual antipodal confirmer scaled by 1/(2t). For any competing g, its complementary normalized original effect supplies the reverse inequality; the budget is not defined to be a reciprocal."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-full-face-budget"), DeclarationHandle.Create(Owner + "original_full_face_budget"),
                H("All affine positive functions and sharp common family budget"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For the same original hypotheses and an arbitrary full chart, one common t gives the directional attained optimum. Every affine h on the coordinate space that is nonnegative on the closed unit ball has an actual linear extension g nonnegative on the entire C. If h is also at most one on that ball, this same g is at most u/(2t) on all C. Conversely every real B that supplies such bounded positive lifts for every affine face effect must satisfy 1/(2t)<=B. The Riesz representation h=c+inner(b,z), c>=norm(b), produces the lift (c-norm(b))u+2 norm(b)g(b/norm(b)); constant h is treated separately. The directional face effects give sharpness. No simultaneous joint instrument or unital positive linear extension operator is asserted.")),
                    Paragraph(Text("The literal individual-optimum formulation uses H, all affine h between zero and one on the entire closed coordinate ball. For each h, let J(h) be the infimum, over all original positive linear extensions g of h, of max over x in K of g(x). Then sup over h in H of J(h) equals 1/(2t). Compactness of K makes each maximum finite and attained. The common bounded lifts give J(h)<=1/(2t) for every h. For an actual directional face effect h(z)=(1+inner(v,z))/2, every positive extension has maximum at least 1/(2t), because that maximum is an admissible directional budget; the supplied sharp extension attains equality. Thus the family supremum and this individual optimum are both attained. This is an application of the sharp full-family theorem, with no additional retained binding declaration."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-chart-independence"), DeclarationHandle.Create(Owner + "original_chart_independence"),
                H("Intrinsic optimality under arbitrary charts"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For any two complete charts a and b of the same original D(p), there is one positive t<=1/2 such that extensionBudget(a,v)=1/(2t) for every unit direction of a and extensionBudget(b,w)=1/(2t) for every unit direction of b. Whole face-effect lifts transport through actual original linear extensions and the equality of the two complete chart images. Sharpness in both directions identifies the numerical optima; no orthogonal coordinate change is supplied as an assumption."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-common-chart-scale"), DeclarationHandle.Create(Owner + "original_common_chart_scale"),
                H("One coefficient in every chart and every mixed input"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Fix any reference chart of D(p). One t>0, t<=1/2 works in every complete chart b of that same D(p), in every unit direction v, and at every original pure q=b(v). The reciprocal budget is feasible and optimal and equals the actual infimum. An actual confirmer of q realizes the affine formula on the whole chart and the comparison formula on every mixed coordinate in its closed unit ball. Chart independence of the optimum identifies the coefficients in all charts. The theorem does not identify scales of different original exclusion faces."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-uniform-comparison"), DeclarationHandle.Create(Owner + "original_uniform_comparison"),
                H("All mixed inputs of every pure row"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Strict positivity and generation give one finite L>0 such that abs(T(p,x)-T(p,y))<=L norm(x-y) for every original pure p and all original mixed x,y in K. This consumed helper directly uses the original frozen CommonOldExclusionConfirmation.comparison_lipschitz owner, enlarging its bound to a positive constant. It provides no independent new mathematical content or escape witness. Neither EB nor PR nor Inj is needed."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-scale-axis-bound"), DeclarationHandle.Create(Owner + "original_scale_axis_bound"),
                H("Universal actual scale-to-axis estimate"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Under closedness, strict positivity, generation, EB and pure PR, one L>0 works at every original pure p and every complete chart a. A positive common scale t<=1/2 has extensionBudget(a,v)=1/(2t) in every unit direction and 2t<=L norm(a(v)-a(-v)). These are the same actual comparison coefficient and original optimal budget, using all mixed inputs of the original scale owner."))), DescribeRole.Theorem)
,
            Describe.Lean(DescribeId.Create("original-bounded-budget-noncollapse"), DeclarationHandle.Create(Owner + "original_bounded_budget_noncollapse"),
                H("Finite budget on arbitrary whole-P label sets"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For any set U of original pure labels and real B>0, assume every actual chart and unit direction at every p in U has extensionBudget<=B. There is a single delta>0 with delta<=diam(D(p)) for all p in U, explicitly delta=1/(B L) for the universal comparison bound. U is an arbitrary subset of the entire P; it may be a neighborhood containing labels outside P0. This is the noncollapse direction of the local-budget argument. The reverse implication is provided by original_noncollapse_bounded_budget, and original_local_budget_iff combines them in open neighborhoods of all P."))), DescribeRole.Theorem))));
}
